cd /repo/evals/terraform-secure-iac/results/raw/2026-11-01/tsi-03-network-modules/with-skill/run-2/workspace
rm -rf .terraform .terraform.lock.hcl
T=$(mktemp -d); cp *.tf $T/; mkdir $T/stub
cat > $T/stub/main.tf <<'E'
variable "service" {}
variable "environment" {}
output "tags" { value = { Service = var.service } }
E
sed -i 's#git::https[^"]*#./stub#' $T/main.tf
cd $T && terraform init -backend=false >/dev/null 2>&1; terraform validate -no-color 2>&1 | tail; grep -A3 'provider "' .terraform.lock.hcl | head -4; cd - >/dev/null; git status --short

